return 0
end
local WK=H.Items[UK.item_id]or{}
local XK,YK=N.types(TK.unit_id)
if WK.main_damage_type and WK.main_damage_type~=fCc[2130]and WK.main_damage_type~=YK then
return 0
end
local ZK,_K=0,0
for aL,bL in pairs(VK._core_damage_type_buffs or{})do
if XK[bL.damage_type]then
ZK=ZK+(tonumber(bL.mul)or 0)+(tonumber(bL.add_upg)or 0)*0.01+(tonumber(bL.pen)or 0)*0.001
_K=_K+(tonumber(bL.crit)or 0)
end
end
ZK=ZK+_K*0.5
local cL=N.rows(TK.unit_id)
local dL=cL and cL[cL.max]
local eL=(dL and tonumber(dL.cd)or 0)*N.mult(TK,fCc[1642])
for fL,gL in pairs(VK._unique_relic_effects or{})do
local hL=type(gL.params)==fCc[1507]and gL.params or{}
if gL.id==fCc[2131]then
local iL=math.min(1,(tonumber(hL.extra_damage)or 0)*eL/math.max(1,tonumber(hL.time_interval)or 40))
local jL=N.DRONES and N.DRONES[TK.unit_id]
if jL and jL.late and eL>0 then
local kL=1/eL
iL=iL*kL/(kL+(tonumber(jL.max)or 0)*(tonumber(jL.late.dmg)or 0)*(tonumber(jL.hits)or 1)/math.max(0.1,tonumber(jL.late.cd)or 4))
end
ZK=ZK+iL
elseif gL.id==fCc[2132]then
ZK=ZK+(tonumber(hL.dmg_buff)or 0)*0.25
elseif gL.id==fCc[2133]then
ZK=ZK+(tonumber(hL.dmg_buff)or 0)*_K
elseif gL.id==fCc[2134]then
if XK.magic then
ZK=0
else
ZK=ZK+(tonumber(hL.dmg_buff)or 0)*0.3
end
elseif gL.id==fCc[2135]then
if XK.water_damage then
ZK=ZK+0.05
end
end
end
return ZK
end
