function V.upgradeGain(aab,bab,cab,dab,eab,fab)
local gab,hab=bab[cab],bab[cab+1]
local iab=(gab.cd>0 and gab.damage/gab.cd or 0)
local jab=(hab.cd>0 and hab.damage/hab.cd or 0)*N.aoe(hab.atk,hab.range)/math.max(0.3,N.aoe(gab.atk,gab.range))
local kab=iab>0 and aab*(jab/iab-1)or(fab or 0)
local mab=bab[cab+2]
if mab and cab+1<bab.max and mab.cd>0 and hab.cd>0 and iab>0 then
local nab=aab*((mab.damage/mab.cd)/iab-1)
local oab=dab+mab.cost*eab
if nab/oab>kab/dab then
kab=kab+(nab/oab*dab-kab)*0.5
end
end
local pab=(hab.range or 0)>(gab.range or 0)and(1+((hab.range-gab.range)/math.max(1,gab.range)))or 1
return math.max(0,kab)*pab
end
function V.dpsFor(qab,rab)
if rab<=0 then
return 0
end
local sab={}
for tab,uab in ipairs(qab)do
if not uab.farm and uab.gain>0 then
table.insert(sab,uab)
end
end
table.sort(sab,function(vab,wab)
return vab.gain/vab.cost>wab.gain/wab.cost
end)
local xab,yab=0,0
for zab,Aab in ipairs(sab)do
if rab<=0 then
break
end
yab=Aab.gain/Aab.cost
local Bab=math.min(1,rab/Aab.cost)
xab=xab+Aab.gain*Bab
rab=rab-Aab.cost*Bab
end
return xab+math.max(0,rab)*yab*0.7
end
function V.shieldDps(Cab,Dab,Eab,Fab,Gab,Hab,Iab)
if(Fab or 0)<=0 or(Cab or 0)<=0 or(Gab or 0)<=0 then
return Cab or 0
end
Dab,Eab,Hab=math.max(0.3,Dab or 2),math.max(1,Eab or 1),Hab or 1
local Jab=Cab*Hab*Dab/Eab
return Gab*Eab/((Fab/math.max(1,Iab or 1)+math.max(1,Gab/Jab))*Dab)/Hab
end
function V.shieldGain(Kab,Lab,Mab,Nab,Oab,Pab,Qab,Rab)
local Sab,Uab=N.attackInfo(Lab.atk,Lab.range),N.attackInfo(Nab.atk,Nab.range)
local Vab=V.shieldDps(Kab,(tonumber(Lab.cd)or 2)*(Qab or 1),Sab.n,Oab,Pab,Rab,Sab.hits)
local Wab=V.shieldDps(Mab,(tonumber(Nab.cd)or 2)*(Qab or 1),Uab.n,Oab,Pab,Rab,Uab.hits)
local Xab=math.max(0,((tonumber(Nab.range)or 0)-(tonumber(Lab.range)or 0))/math.max(1,tonumber(Lab.range)or 1))
return math.max(0,Wab-Vab)+Vab*Xab
end
function V.shieldWork(Yab,Zab,_ab,abb,bbb,cbb,dbb,ebb,fbb)
if(abb or 0)<=0 then
return 0
end
local gbb=3*abb*(bbb or 1)/math.max(1,cbb or 20)
if(_ab or 0)>=gbb then
return 0
end
return math.max(1,Yab or 1)*math.max(1,fbb or 1)/math.max(0.3,Zab or 2)*math.min(dbb or 0,ebb or 0)
end
function V.holdGain(hbb,ibb,jbb,kbb)
if not hbb or(ibb or 0)<=0 then
return 0
end
local lbb,mbb=tonumber(hbb.stun)or 0,tonumber(hbb.slowTime)or 0
if lbb<=0 and mbb<=0 then
return 0
end
local nbb,obb=lbb>0 and lbb or mbb,lbb>0 and 1 or(tonumber(hbb.slowPct)or 0.3)
local pbb=obb*nbb/(nbb+(tonumber(hbb.ccCd)or 8))
local qbb=pbb/math.max(0.1,1-pbb)
return ibb*qbb*M.clamp(jbb or 0.5,0,1)*math.min(1,(tonumber(hbb.n)or 1)/2)/(1+(kbb or 0))
end
function V.bleedGain(rbb,sbb,tbb,ubb)
if(rbb or 0)<=0 then
return 0
end
local vbb=sbb or 0
for wbb,xbb in ipairs(tbb or{})do
vbb=math.max(vbb,(tonumber(xbb.hp)or 0)*0.5)
end
return rbb*vbb*(ubb and 0.5 or 1)
end
function V.bleedShare(ybb,zbb,Abb,Bbb)
if ybb<=0 or not zbb then
return 0
end
if Bbb then
return zbb==0 and ybb or ybb/(zbb+1)
end
return Abb<zbb and ybb/(zbb-Abb)or 0
end
function V.keepsUp(Cbb,Dbb,Ebb,Fbb,Gbb)
local Hbb=Cbb.coming
if not(Hbb and#Hbb>0 and Cbb.waveSec)then
return true
end
local Ibb=Cbb.eff or 1
local Jbb=Cbb.money-Ebb
local Kbb=(Cbb.teamDps or 0)*(Cbb.shieldK or 1)+(Fbb or 0)*Ibb+V.dpsFor(Dbb,math.max(0,Jbb))*Ibb
local Lbb=(Cbb.farmNow or 0)+(Gbb or 0)
local Mbb=(Cbb.roadSec or 130)*M.clamp(Cbb.cover or 0.6,0.1,1)
local Nbb=Cbb.hpAlive or 0
for Obb,Pbb in ipairs(Hbb)do
Nbb=math.max(0,Nbb+Pbb.hp-Kbb*Cbb.waveSec)
local Qbb=Kbb*Mbb
if Nbb>Qbb then
return false,Obb,Qbb/math.max(1,Nbb)
end
if Obb< #Hbb then
Kbb=Kbb+V.dpsFor(Dbb,(Pbb.reward or 0)+Lbb)*Ibb*(0.85^Obb)
end
end
return true
end
function V.decide(Rbb,Sbb)
local Tbb=M.clamp(Sbb.cover or 0.6,0.1,1)
local Ubb=math.max(I.clearSec,0.7*(Sbb.roadSec or 50)*Tbb)
local Vbb=(Sbb.clearSec or 0)>Ubb
Sbb.piling=Sbb.piling and Vbb
local Wbb=Sbb.attackers>0 and Sbb.pressure<math.min(I.safeReach,Tbb*0.75)and not Sbb.piling and not Vbb
local Xbb=Sbb.pressure>=math.min(I.dangerReach,Tbb*0.9)or(Sbb.piling and Sbb.enemies>=18)
local Ybb,Zbb
for _bb,acb in ipairs(Rbb)do
if acb.farm then
if I.farmUnits and acb.gain>0 then
acb.payback=acb.cost/acb.gain
if Sbb.left-1>=acb.payback+(Sbb.farmSpare or I.farmSpare)and(not Ybb or acb.payback<Ybb.payback)then
Ybb=acb
end
end
else
acb.ratio=acb.gain/math.max(1,acb.cost)
if not Zbb or acb.ratio>Zbb.ratio then
Zbb=acb
end
end
end
if Sbb.leak and Sbb.attackers>0 then
local bcb
for ccb,dcb in ipairs(Rbb)do
local ecb=not Sbb.airLeak or(dcb.e and Q.cardAir(dcb.e.id))
if dcb.place and not dcb.farm and ecb and dcb.cost<=Sbb.money and not(dcb.e and N.allyBuff(dcb.e.id))and(not bcb or dcb.gain>bcb.gain)then
bcb=dcb
end
end
if bcb then
return bcb,string.format(fCc[2680],math.floor(Sbb.leak*100))
end
end
local fcb=Sbb.future<Sbb.wantLeft*1.1
local gcb,hcb,icb=true,nil,nil
if Ybb then
gcb,hcb,icb=V.keepsUp(Sbb,Rbb,Ybb.cost,0,Ybb.gain)
end
local jcb=Sbb.coming and not V.keepsUp(Sbb,Rbb,0,0,0)
local kcb=false
if Q.random and Ybb and not Xbb and Sbb.attackers>=2 and Ybb.payback<=Sbb.left/3 then
local lcb=0
for mcb,ncb in ipairs(Q.mine or{})do
if N.isFarm(ncb._stats.id.Value)then
lcb=lcb+1
end
end
kcb=not Ybb.place or lcb<4
end
if jcb and Sbb.attackers>0 then
Xbb=true
end
local ocb=math.max(1,Sbb.incomeRate or 20)
local pcb=Sbb.waveSec or 20
local function qcb(rcb,scb,tcb)
local ucb=math.max(0,(rcb.cost-Sbb.money)/ocb)
local vcb=rcb.gain*math.max(0,tcb-ucb)
if scb then
local wcb=math.max(0,Sbb.money-rcb.cost)
local xcb=ucb+math.max(0,(scb.cost-wcb)/ocb)
vcb=vcb+scb.gain*math.max(0,tcb-xcb)
end
return vcb
end
local ycb,zcb
if Sbb.attackers==0 and Zbb then
local Acb=4*pcb
local Bcb={}
for Ccb,Dcb in ipairs(Rbb)do
if Dcb.place and not Dcb.farm then
table.insert(Bcb,{o=Dcb,v=qcb(Dcb,nil,Acb)})
end
end
table.sort(Bcb,function(Ecb,Fcb)
return Ecb.v>Fcb.v
end)
local Gcb=Sbb.opener and Bcb[Sbb.opener]and Sbb.opener or 1
local Hcb=Bcb[Gcb]and Bcb[Gcb].o
ycb,zcb=Hcb or Zbb,Gcb>1 and fCc[2681]or fCc[2682]
elseif Ybb and Wbb and fcb and not Xbb and gcb then
ycb=Ybb
zcb=string.format(fCc[2683],Ybb.payback,Sbb.left,Sbb.coming and#Sbb.coming or 0)
elseif kcb then
ycb=Ybb
zcb=string.format(fCc[2684],Ybb.payback,Sbb.left)
elseif Zbb then
ycb=Zbb
if jcb then
zcb=string.format(fCc[2685])
elseif Xbb then
zcb=string.format(fCc[2686],math.floor(Sbb.pressure*100),math.floor(Tbb*100))
elseif Ybb and not gcb then
zcb=string.format(fCc[2687],hcb or 1,math.floor((icb or 0)*100))
elseif Ybb and Vbb then
zcb=string.format(fCc[2688],math.min(999,math.floor(Sbb.clearSec)),math.floor(Ubb))
elseif Ybb and Sbb.piling then
zcb=string.format(fCc[2689],Sbb.enemies)
elseif Ybb and not Wbb then
zcb=fCc[2690]
elseif Ybb and not fcb then
zcb=fCc[2691]
else
zcb=fCc[2692]
end
end
if not ycb then
return nil
end
if ycb.cost>Sbb.money then
local Icb
if not ycb.farm then
local Jcb=((Sbb.pressure or 0)>=0.95 and 0.5 or Xbb and 2 or 6)*pcb
local Kcb
for Lcb,Mcb in ipairs(Rbb)do
if not Mcb.farm and Mcb~=ycb and Mcb.cost<=Sbb.money then
local Ncb=qcb(Mcb,ycb,Jcb)
local Ocb=qcb(ycb,Mcb,Jcb)
if Ncb>Ocb and(not Kcb or Ncb>Kcb)then
Icb,Kcb=Mcb,Ncb
end
end
end
end
if not Icb then
return nil,nil,string.format(fCc[2693],M.fmt(ycb.cost),ycb.what or fCc[1745],math.ceil((ycb.cost-Sbb.money)/ocb),math.floor(ocb),zcb)
end
ycb,zcb=Icb,zcb..fCc[2694]
end
return ycb,zcb
end
