local OHb=NHb._stats
if not N.isFarm(OHb.id.Value)and OHb:FindFirstChild(fCc[1644])then
table.insert(LHb,{p=M.flat(NHb:GetPivot().Position),r=OHb.range.Value*(N.SUMMONER[OHb.id.Value]and N.SUMMONER[OHb.id.Value].reach or 1),air=Q.canAir(NHb)})
end
