local PHb,QHb=0,0
if#LHb>0 then
for RHb,SHb in ipairs(Q.samples)do
if SHb.prog>QHb then
local THb=M.flat(SHb.pos)
for UHb,VHb in ipairs(LHb)do
if(THb-VHb.p).Magnitude<=VHb.r then
if SHb.prog>PHb then
PHb=SHb.prog
end
if VHb.air then
