local aIb=M.flat(_Hb.pos)
for bIb,cIb in ipairs(LHb)do
if(aIb-cIb.p).Magnitude<=cIb.r then
local dIb=tostring(_Hb.lane)
YHb[dIb]=(YHb[dIb]or 0)+1
if _Hb.prog>(WHb[dIb]or 0)then
WHb[dIb]=_Hb.prog
end
break
end
end
end
local eIb,fIb={},0
for gIb,hIb in pairs(XHb.by)do
