if#LHb>0 then
for nIb,oIb in ipairs(KHb)do
local pIb=(Q.laneW and oIb.lane and WHb[oIb.lane])or PHb
if oIb.hp>0 and oIb.prog>pIb+0.02 and oIb.prog>(kIb or 0)then
kIb,mIb=oIb.prog,Q.laneW and oIb.lane or nil
