if oIb.hp>0 and oIb.fly and oIb.prog>QHb+0.02 then
lIb=true
end
end
end
local qIb= #LHb>0 and(Q.pressure or 0)>=PHb-0.08
return{covEnd=PHb,airEnd=QHb,leak=kIb,leakLane=mIb,covL=WHb,airLeak=lIb,push=qIb,units= #LHb}
end
