PTb=_Tb/qTb*100+Q.cover(OTb,wSb,true)*0.05
else
local dUb=Q.cover(OTb,wSb,true,mSb)
if xSb then
dUb=Q.cover(OTb,xSb)+dUb*0.25
end
PTb=dUb+(LTb and 0 or(1-Q.progressAt(OTb))*0.5)
local eUb=0
for fUb,gUb in ipairs(oTb)do
local hUb=gUb.b.types[nTb]
if hUb and(M.flat(gUb.pos)-M.flat(OTb)).Magnitude<=gUb.range then
