end
if xTb and(M.flat(xTb)-M.flat(OTb)).Magnitude<=yTb then
PTb=PTb+1e6
end
if zTb then
table.insert(zTb,{p=OTb,sc=PTb})
end
if not ITb or PTb>ITb then
