end
end
end
if ySb and#pTb>0 and HTb then
local iUb=false
for jUb,kUb in ipairs(pTb)do
if(M.flat(kUb.pos)-M.flat(HTb)).Magnitude<=wSb then
iUb=true
break
end
end
if not iUb then
return nil,0
end
end
if zTb and#zTb>0 then
table.sort(zTb,function(lUb,mUb)
return lUb.sc>mUb.sc
end)
for nUb=1,math.min(15,#zTb)do
